"""Build an offline, linked Plotly prototype from existing analysis outputs."""
from pathlib import Path
import json, zipfile
import pandas as pd
from plotly.offline import get_plotlyjs
R=Path(__file__).resolve().parents[1]
z=zipfile.ZipFile(R/'data/raw/bls_projections_2024_2034.zip')
x=pd.read_excel(z.open('2024-34/occupation.xlsx'),sheet_name='Table 1.2',header=1)
assert '2024' in x.columns[3] and '2034' in x.columns[4]
b=x[x['Occupation type']=='Summary']; groups={str(r.iloc[1])[:2]:r.iloc[0] for _,r in b.iterrows() if str(r.iloc[1]).endswith('-0000') and str(r.iloc[1])!='00-0000'}
d=x[x['Occupation type']=='Line item'].iloc[:,[0,1,3,4,8]].copy();d.columns=['title','code','emp2024','emp2034','growth']
for c in ['emp2024','emp2034','growth']:d[c]=pd.to_numeric(d[c],errors='raise')
d[['emp2024','emp2034']]*=1000
d['title']=d['title'].str.strip()
assert d.code.is_unique
a=pd.read_csv(R/'data/raw/job_exposure.csv').rename(columns={'occ_code':'code'})
f=pd.read_csv(R/'results/tasks/soc_task_metrics.csv',dtype={'code':str})
d=d.merge(a[['code','observed_exposure']],on='code',validate='one_to_one').merge(f,on='code',validate='one_to_one');d=d[d.coverage>=.95].copy();d['major']=d.code.str[:2]
d.to_csv(R/'data/processed/projections_2024_2034_task_sample.csv',index=False)
t=pd.read_csv(R/'results/tasks/task_matches.csv',dtype={'code':str})
from plotly.colors import qualitative
colors=dict(zip(sorted(groups),qualitative.Alphabet))
print('Matched projection sample:',len(d),'Max exposure/breadth:',d.observed_exposure.max(),d.breadth.max())
major_totals={str(r.iloc[1])[:2]:float(r.iloc[3])*1000 for _,r in b.iterrows() if str(r.iloc[1]).endswith('-0000') and str(r.iloc[1])!='00-0000'}
aggregates=[]
for code,g in d.groupby('major'):
    base=float(g.emp2024.sum()); future=float(g.emp2034.sum())
    aggregates.append(dict(code=code,major=code,title=groups[code].strip(),emp2024=base,emp2034=future,growth=100*(future/base-1),observed_exposure=float((g.observed_exposure*g.emp2024).sum()/base),breadth=float((g.breadth*g.emp2024).sum()/base),n=len(g),employment_coverage=base/major_totals[code],official_emp2024=major_totals[code]))
agg=pd.DataFrame(aggregates);assert len(agg)==22 and abs(agg.emp2024.sum()-d.emp2024.sum())<.01
assert agg.employment_coverage.between(0,1.001).all()
agg.to_csv(R/'data/processed/projections_major_groups.csv',index=False)
rows=json.loads(d.to_json(orient='records'));tasks={c:json.loads(a[['Task','penetration']].to_json(orient='records')) for c,a in t[t.code.isin(d.code)].groupby('code')}
